files.content:
.header {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: 1fr min-content;
  padding: var(--section-padding, 20px 40px);
  container-type: inline-size;
}

.text-content {
  padding: var(--section-padding, 20px 40px);
}

.icons {
  container-type: inline-size;
  padding: var(--section-padding, 20px 40px);
}

.icons__text-wrapper {
  margin-block-end: 1em;
}

@media (width >= 1000px) {
  .hero-and-form {
    display: grid;
    grid-template-columns: 2fr 1fr;
  }

  .icons {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
  }

  .icons__text-wrapper {
    margin-block-end: 0;
  }
}

@media (width >= 1400px) {
  .icons {
    grid-template-columns: 2fr 1fr;
  }
}
@container (width >= 500px) {
  .icons-list {
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  }
}

.icons-list {
  display: grid;
  place-items: center;
  gap: 20px;
  inline-size: 100%;
}

.icons-list__item {
  inline-size: 100%;
  border: 2px solid currentColor;
}

.icons-list__link {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 20px;
}

.icons-list__link:hover {
  text-decoration: none;
  background-color: var(--icons-list-link-hover-background-color, #80d994);
}

.icons-list__image {
  inline-size: 30%;
}

.icons-list__text {
  font-weight: bold;
  font-size: 18px;
  text-align: center;
  text-transform: uppercase;
}
@container (width >= 500px) {
  .icons-list { grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); }
}
